import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int lines = 0;
        int errors = 0;
        while (sc.hasNextLine()) {
            String line = sc.nextLine();
            String[] p = line.trim().split("\\s+");
            int a = Integer.parseInt(p[0]);
            int b = Integer.parseInt(p[1]);
            System.out.println(a + " / " + b + " = " + (a / b) + " remainder " + (a % b));
            lines++; // TODO: try / catch / finally
        }
        System.out.println("Processed " + lines + " line(s), " + errors + " error(s)");
    }
}

#!/usr/bin/env node
// CuongThai Code Lab · PRO192 (Java OOP) — LOCAL GRADER · MÁY CHẤM CHẠY TRÊN MÁY BẠN
// Exercise / Bài: pro192-6-1-safe-divide — try/catch: a calculator that never crashes
//
//   node cham.mjs            compile src/ with javac, run every case, check the rules, print the score
//   node cham.mjs --show     also print your whole output for every case (Hiện toàn bộ output của bạn)
