const DE = {
 "id": "pro192-6-1-safe-divide",
 "title": "try/catch: a calculator that never crashes",
 "src": "src",
 "extra": [],
 "main": "Main",
 "javaMin": 8,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "rules": [
  {
   "id": "R1",
   "en": "catch the specific exceptions, not Exception/Throwable",
   "vi": "bắt đúng loại, không bắt Exception/Throwable",
   "re": "catch\\s*\\(\\s*(final\\s+)?(Exception|Throwable|RuntimeException)\\s+\\w+\\s*\\)"
  },
  {
   "id": "R2",
   "en": "uses finally",
   "vi": "có dùng finally",
   "re": "\\bfinally\\b",
   "need": true
  }
 ],
 "cases": [
  {
   "name": "good lines and both kinds of error",
   "input": "17 5\n-7 2\nx 2\n4 0\n100 7\n",
   "expected": "17 / 5 = 3 remainder 2\n-7 / 2 = -3 remainder -1\nLine 3: \"x 2\" is not two integers\nLine 4: cannot divide by zero\n100 / 7 = 14 remainder 2\nProcessed 5 line(s), 2 error(s)\n"
  },
  {
   "h": ""
  },
  {
   "h": "eyJuYW1lIjoibm8gaW5wdXQgYXQgYWxsIiwiaW5wdXQiOiJcbiIsImV4cGVjdGVkIjoiTGluZSAxOiBcIlwiIGlzIG5vdCB0d28gaW50ZWdlcnNcblByb2Nlc3NlZCAxIGxpbmUocyksIDEgZXJyb3IocylcbiJ9"
  }
