const DE = {
 "id": "pro192-6-1-throw-iae",
 "title": "throw with a reason: a constructor that refuses bad data",
 "src": "src",
 "extra": [
  "cham"
 ],
 "main": "KiemTra",
 "javaMin": 8,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "rules": [],
 "cases": [
  {
   "name": "valid product, each kind of refusal",
   "input": "SP001;Pen;5000;100\nsp002;Pen;5000;1\nSP003;   ;5000;1\nSP004;Ink;-1;1\nSP005;Box;0;10001\n",
   "expected": "OK SP001 Pen 5000 x100\nREFUSED IllegalArgumentException: code must look like SP001: sp002\nREFUSED IllegalArgumentException: name must not be blank\nREFUSED IllegalArgumentException: price must be >= 0: -1\nREFUSED IllegalArgumentException: quantity must be 0..10000: 10001\n"
  },
  {
   "name": "setPrice keeps the rule",
   "input": "AB123;Notebook;12000;0\nSETPRICE;-5\nSETPRICE;15000\n",
   "expected": "OK AB123 Notebook 12000 x0\nREFUSED IllegalArgumentException: price must be >= 0: -5\nOK AB123 Notebook 15000 x0\n"
