import java.util.List;

// GIVEN — do not change.
public class Resource implements AutoCloseable {
    private final String name;
    private final List<String> log;

    public Resource(String name, List<String> log) {
        this.name = name;
        this.log = log;
        log.add("open " + name);
    }

    public void use(String step) {
        if (step.equals("boom")) {
            throw new IllegalStateException(name + " broke at " + step);
        }
        log.add(name + " " + step);
    }

    @Override
    public void close() {
        log.add("close " + name);
    }
}

import java.util.ArrayList;
import java.util.List;

public class Job {
    public static List<String> run(String[] steps) {
        List<String> log = new ArrayList<>();
        Resource db = new Resource("DB", log);
        Resource file = new Resource("FILE", log);
        for (String step : steps) {
            db.use(step);
        }
        log.add("done"); // TODO: try-with-resources + catch + finally
        return log;
    }
}

import java.util.Scanner;

public class Main {
